steps.script:
if HandoffManager._visible:
	HandoffManager._on_ready_pressed()
return HandoffManager._visible

var main = tree.root.get_node("Main")
TerrainManager.set_meta("home_area_saved_layout", TerrainManager.current_layout)
TerrainManager.load_terrain_layout("take_and_hold_vs_reconnaissance_1")
var units = GameState.state["units"]
var boyz_xy = []
for i in range(10):
	boyz_xy.append(Vector2([31.6, 33.2][i % 2], 49.0 + 1.4 * int(i / 2)) * 40.0)
var guard_xy = []
for k in range(4):
	guard_xy.append(Vector2(18.0 + [-0.85, 0.85][k % 2], 57.0 + [-0.85, 0.85][int(k / 2)]) * 40.0)
var keep = {"U_CUSTODIAN_GUARD_B": guard_xy, "U_BOYZ_K": boyz_xy}
for uid in units:
	if keep.has(uid):
		var i = 0
		for m in units[uid].get("models", []):
			if not m.get("alive", true):
				continue
			var p = keep[uid][i]
			m["position"] = {"x": p.x, "y": p.y}
			i += 1
		units[uid]["status"] = GameStateData.UnitStatus.DEPLOYED
		units[uid].get("flags", {}).erase("last_shot_idx")
		units[uid].get("flags", {}).erase("shot_recently")
	else:
		for m in units[uid].get("models", []):
			m["alive"] = false
main._recreate_unit_visuals()
main.get_node("ShootingController")._refresh_unit_list(false)
return "%s|%d" % [TerrainManager.current_layout, TerrainManager.terrain_features.size()]

var area = {}
var ruins = []
for p in TerrainManager.terrain_features:
	if str(p.get("id", "")) == "area-large-7":
		area = p
	if str(p.get("parent_area_id", "")) == "area-large-7":
		ruins.append("%s:%s" % [str(p.get("id", "")), TerrainManager.category_of(p)])
ruins.sort()
var ruins_s = PackedStringArray(ruins)
var only_area = 0
for m in GameState.get_unit("U_BOYZ_K")["models"]:
	var ids = []
	for p in TerrainManager.pieces_model_within(m):
		ids.append(str(p.get("id", "")))
	if ids == ["area-large-7"]:
		only_area += 1
print("[%s] area-large-7: category=%s objective_role=%s features=%s; Boyz models within it (and nothing else): %d" % ["terrain_home_area_hidden_obscuring_11e", TerrainManager.category_of(area), str(area.get("objective_role", "")), str(ruins), only_area])
return "%s|%s|%s|%d" % [TerrainManager.category_of(area), str(area.get("objective_role", "")), ",".join(ruins_s), only_area]

var u = GameState.get_unit("U_BOYZ_K")
var n = 0
for m in u["models"]:
	if not m.get("alive", true):
		continue
	if not TerrainManager.is_model_hidden(m, u):
		return "model %s NOT hidden" % str(m.get("id", "?"))
	n += 1
return n == 10

var g = GameState.state["units"]["U_CUSTODIAN_GUARD_B"]
var k = 0
for m in g["models"]:
	if m.get("alive", true):
		m["position"] = {"x": (12.0 + [-0.85, 0.85][k % 2]) * 40.0, "y": (57.0 + [-0.85, 0.85][int(k / 2)]) * 40.0}
		k += 1
tree.root.get_node("Main")._recreate_unit_visuals()
return "ok"

var why = RulesEngine.explain_target_ineligibility("U_CUSTODIAN_GUARD_B", "U_BOYZ_K", GameState.create_snapshot(false))
print("[terrain_home_area_hidden_obscuring_11e] explain (Guard ~17.4in away): %s" % str(why))
return "%s|%s" % [why.code, str(int(round(float(why.get("detection_in", -1.0)))))]

var list = tree.root.get_node("Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/DeclarationBox/ShooterUnitList")
if list.item_count < 1 or not list.get_item_text(0).begins_with("Custodian Guard"):
	return "row 0 is not Custodian Guard"
return "ok"

var sc = tree.root.get_node("Main").get_node("ShootingController")
print("[terrain_home_area_hidden_obscuring_11e] controller eligible_targets: %s" % str(sc.eligible_targets.keys()))
return "%s|%s" % [str(sc.active_shooter_id), str(sc.eligible_targets.has("U_BOYZ_K"))]

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
for ol in lv.overview_lines:
	if ol["tgt"] == "U_BOYZ_K":
		print("[terrain_home_area_hidden_obscuring_11e] overlay line: verdict=%s code=%s label=%s" % [ol["verdict"], ol.get("reason_code", ""), ol.get("label", "")])
		return "%s|%s|%s" % [ol["verdict"], ol.get("reason_code", ""), str(str(ol.get("label", "")).begins_with("Hidden unit: seen within 15\" (your best LoS "))]
return "no line"

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
for e in lv.drawn_reason_labels:
	if e["tgt"] == "U_BOYZ_K":
		print("[terrain_home_area_hidden_obscuring_11e] drawn label: %s (%s)" % [e["text"], e["verdict"]])
		return "%s|%s" % [e["verdict"], str(str(e["text"]).begins_with("Hidden unit: seen within 15\" (your best LoS "))]
return "not drawn: %s" % str(lv.drawn_reason_labels)

var units = GameState.state["units"]
var i = 0
for m in units["U_BOYZ_K"]["models"]:
	if m.get("alive", true):
		m["position"] = {"x": (30.9 + 0.7 * (i % 5)) * 40.0, "y": (57.3 + 1.4 * int(i / 5)) * 40.0}
		i += 1
var k = 0
for m in units["U_CUSTODIAN_GUARD_B"]["models"]:
	if m.get("alive", true):
		m["position"] = {"x": (32.4 + [-0.85, 0.85][k % 2]) * 40.0, "y": (46.0 + [-0.85, 0.85][int(k / 2)]) * 40.0}
		k += 1
tree.root.get_node("Main")._recreate_unit_visuals()
var in_terrain = 0
for uid in ["U_BOYZ_K", "U_CUSTODIAN_GUARD_B"]:
	for m in units[uid]["models"]:
		if m.get("alive", true) and not TerrainManager.pieces_model_within(m).is_empty():
			in_terrain += 1
var crossed = {}
for a in units["U_CUSTODIAN_GUARD_B"]["models"]:
	for b in units["U_BOYZ_K"]["models"]:
		for p in TerrainManager.features_crossing(Vector2(a.position.x, a.position.y), Vector2(b.position.x, b.position.y)):
			crossed[str(p.get("id", ""))] = true
print("[terrain_home_area_hidden_obscuring_11e] part B: models in terrain=%d, centre lines cross %s" % [in_terrain, str(crossed.keys())])
return "%d|%s" % [in_terrain, ",".join(PackedStringArray(crossed.keys()))]

var why = RulesEngine.explain_target_ineligibility("U_CUSTODIAN_GUARD_B", "U_BOYZ_K", GameState.create_snapshot(false))
print("[terrain_home_area_hidden_obscuring_11e] explain (across the home area): %s" % str(why))
return str(why.code)

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
for ol in lv.overview_lines:
	if ol["tgt"] == "U_BOYZ_K":
		print("[terrain_home_area_hidden_obscuring_11e] overlay line: verdict=%s code=%s" % [ol["verdict"], ol.get("reason_code", "")])
		return "%s|%s" % [ol["verdict"], ol.get("reason_code", "")]
return "no line"

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
lv.hide_overview()
var prev = str(TerrainManager.get_meta("home_area_saved_layout", ""))
TerrainManager.remove_meta("home_area_saved_layout")
if prev != "":
	TerrainManager.load_terrain_layout(prev)
return "%d|%s" % [lv.overview_lines.size(), str(TerrainManager.current_layout == prev)]
